import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";

const AdmListCurso = () => {
  const [cursos, setCursos] = useState([]);
  const [filtro, setFiltro] = useState("");
  const [estatisticas, setEstatisticas] = useState(null);
  const [mostrarEstatisticas, setMostrarEstatisticas] = useState(false);
  const navigate = useNavigate();

  // Função para buscar os cursos no backend
  const fetchCursos = async () => {
    try {
      const resposta = await fetch("http://localhost:5000/cursos");
      if (resposta.ok) {
        const dados = await resposta.json();
        setCursos(dados);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Função para buscar estatísticas
  const fetchEstatisticas = async () => {
    try {
      const resposta = await fetch("http://localhost:5000/cursos/estatisticas");
      if (resposta.ok) {
        const dados = await resposta.json();
        setEstatisticas(dados);
      } else {
        console.error("Erro ao buscar estatísticas");
      }
    } catch (error) {
      console.error("Erro na requisição de estatísticas:", error);
    }
  };

  // Buscar cursos e estatísticas ao montar o componente
  useEffect(() => {
    fetchCursos();
    fetchEstatisticas();
  }, []);

  // ... (restante das funções existentes permanecem iguais)

  return (
    <div className="container mt-4">
      {/* Cabeçalho e navegação permanecem iguais */}

      {/* Seção de Estatísticas */}
      <div className="card mt-4 mb-4">
        <div className="card-header d-flex justify-content-between align-items-center">
          <h5 className="mb-0">Estatísticas dos Cursos</h5>
          <button
            className="btn btn-sm btn-outline-secondary"
            onClick={() => setMostrarEstatisticas(!mostrarEstatisticas)}
          >
            {mostrarEstatisticas ? "Ocultar" : "Mostrar"}
          </button>
        </div>

        {mostrarEstatisticas && estatisticas && (
          <div className="card-body">
            <div className="row mb-3">
              <div className="col-md-4">
                <div className="card text-white bg-primary">
                  <div className="card-body">
                    <h5 className="card-title">Total de Cursos</h5>
                    <p className="card-text display-4">
                      {estatisticas.totalCursos}
                    </p>
                  </div>
                </div>
              </div>
              <div className="col-md-4">
                <div className="card text-white bg-success">
                  <div className="card-body">
                    <h5 className="card-title">Total de Alunos</h5>
                    <p className="card-text display-4">
                      {estatisticas.totalAlunos}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <h6>Cursos com mais alunos:</h6>
            <div className="table-responsive">
              <table className="table table-striped">
                <thead>
                  <tr>
                    <th>Curso</th>
                    <th>Alunos</th>
                    <th>Percentagem</th>
                    <th>Progresso</th>
                  </tr>
                </thead>
                <tbody>
                  {estatisticas.cursos.map((curso) => (
                    <tr key={curso.id}>
                      <td>{curso.nome}</td>
                      <td>{curso.numAlunos}</td>
                      <td>{curso.percentagem}%</td>
                      <td>
                        <div className="progress">
                          <div
                            className="progress-bar bg-info"
                            role="progressbar"
                            style={{ width: `${curso.percentagem}%` }}
                            aria-valuenow={curso.percentagem}
                            aria-valuemin="0"
                            aria-valuemax="100"
                          ></div>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Restante do seu código permanece igual */}
      {/* ... */}
    </div>
  );
};

export default AdmListCurso;
